def calc(expr):
    s = expr
    i = 0
    n = len(s)

    def skip_ws():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def peek():
        skip_ws()
        if i < n:
            return s[i]
        return None

    def idiv(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_number():
        nonlocal i
        skip_ws()
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    def parse_primary():
        nonlocal i
        c = peek()
        if c == '(':
            i += 1  # consume '('
            val = parse_expr()
            skip_ws()
            if i < n and s[i] == ')':
                i += 1
            return val
        else:
            return parse_number()

    def parse_unary():
        nonlocal i
        c = peek()
        if c == '-':
            i += 1
            return -parse_unary()
        return parse_primary()

    def parse_term():
        nonlocal i
        val = parse_unary()
        while True:
            c = peek()
            if c == '*':
                i += 1
                rhs = parse_unary()
                val = val * rhs
            elif c == '/':
                i += 1
                rhs = parse_unary()
                val = idiv(val, rhs)
            else:
                break
        return val

    def parse_expr():
        nonlocal i
        val = parse_term()
        while True:
            c = peek()
            if c == '+':
                i += 1
                rhs = parse_term()
                val = val + rhs
            elif c == '-':
                i += 1
                rhs = parse_term()
                val = val - rhs
            else:
                break
        return val

    result = parse_expr()
    return result

